(4203129, 605813, 43774, '<td valign="top">Great idea for this challenge! Good DOF</td>', 'Great idea for this challenge! Good DOF', '2007-10-29 08:48:14.000000', NULL, 1),
(4203131, 605719, 43774, '<td valign="top">Sorry, not fond of the overexposed look.</td>', 'Sorry, not fond of the overexposed look.', '2007-10-29 08:48:41.000000', NULL, 1),
(4203132, 605887, 43774, '<td valign="top">Love the textures and muted colours.</td>', 'Love the textures and muted colours.', '2007-10-29 08:49:06.000000', NULL, 1),
(4203134, 605781, 43774, '<td valign="top">What a great composition!</td>', 'What a great composition!', '2007-10-29 08:49:19.000000', NULL, 1),
(4203137, 605910, 43774, '<td valign="top">A lovely scene but it is not really noticeable that this is a cemetery. I was wondering at first what your title had to do with the photo then I saw the flowers which I assume are on a grave.</td>', 'A lovely scene but it is not really noticeable that this is a cemetery. I was wondering at first what your title had to do with the photo then I saw the flowers which I assume are on a grave.', '2007-10-29 08:50:22.000000', NULL, 1),
(4203140, 605824, 43774, '<td valign="top">What a beautiful photo</td>', 'What a beautiful photo', '2007-10-29 08:51:05.000000', NULL, 1),
(4203142, 605560, 43774, '<td valign="top">Wow that looks like a spider, very cool plant</td>', 'Wow that looks like a spider, very cool plant', '2007-10-29 08:51:39.000000', NULL, 1),
(4203148, 605326, 43774, '<td valign="top">Very nice, great composition, good DOF</td>', 'Very nice, great composition, good DOF', '2007-10-29 08:53:26.000000', NULL, 1),
