(4203154, 605325, 43774, '<td valign="top">Love the detail but I am not fond of whatever you did to the edges.</td>', 'Love the detail but I am not fond of whatever you did to the edges.', '2007-10-29 08:55:14.000000', NULL, 1),
(4203155, 605808, 43774, '<td valign="top">Very clear</td>', 'Very clear', '2007-10-29 08:55:40.000000', NULL, 1),
(4203157, 605903, 43774, '<td valign="top">I think you need to work on your lighting or white balance. This has a yellowish cast. Interesting idea for this challenge though</td>', 'I think you need to work on your lighting or white balance. This has a yellowish cast. Interesting idea for this challenge though', '2007-10-29 08:56:22.000000', NULL, 1),
(4203158, 605814, 43774, '<td valign="top">Very clear.</td>', 'Very clear.', '2007-10-29 08:57:10.000000', NULL, 1),
(4203161, 604196, 43774, '<td valign="top">Very creative how her reflection is older and more haggard looking than her real self.</td>', 'Very creative how her reflection is older and more haggard looking than her real self.', '2007-10-29 08:58:14.000000', NULL, 1),
(4203162, 605704, 43774, '<td valign="top">I like the green mist because it does tie into your title and the challenge. I do not like the pink and blue lines, they look fake and have no relevance to the photo. Sorry. If they were not there I''d score this at least 2 points higher.</td>', 'I like the green mist because it does tie into your title and the challenge. I do not like the pink and blue lines, they look fake and have no relevance to the photo. Sorry. If they were not there I''d score this at least 2 points higher.', '2007-10-29 09:00:09.000000', NULL, 1),
(4203165, 605818, 43774, '<td valign="top">I do not understand your title, sorry.</td>', 'I do not understand your title, sorry.', '2007-10-29 09:00:35.000000', NULL, 1),
(4203169, 605812, 43774, '<td valign="top">"Break", not "Brake" (sorry, former English teacher, I always notice spelling mistakes).<br/> <br/>Lovely photo, shed is a bit too centered though.</td>', '"Break", not "Brake" (sorry, former English teacher, I always notice spelling mistakes). Lovely photo, shed is a bit too centered though.', '2007-10-29 09:01:16.000000', NULL, 1),
(4203170, 605840, 43774, '<td valign="top">Just a step to the left would have improved the perspective on this so much!</td>', 'Just a step to the left would have improved the perspective on this so much!', '2007-10-29 09:01:43.000000', NULL, 1),
(4203172, 605909, 43774, '<td valign="top">Dramatic, artsy image.</td>', 'Dramatic, artsy image.', '2007-10-29 09:01:56.000000', NULL, 1),
(4203173, 605323, 43774, '<td valign="top">Love the tones, dramatic sky</td>', 'Love the tones, dramatic sky', '2007-10-29 09:02:08.000000', NULL, 1),
