(4203176, 604895, 43774, '<td valign="top">Creative!!</td>', 'Creative!!', '2007-10-29 09:03:31.000000', NULL, 1),
(4203179, 605610, 43774, '<td valign="top">Very nice, great getting a green leaf with some colour in it, fits the challenge well. Good DOF</td>', 'Very nice, great getting a green leaf with some colour in it, fits the challenge well. Good DOF', '2007-10-29 09:04:43.000000', NULL, 1),
(4203181, 605846, 43774, '<td valign="top">Love the backlighting and the white background.</td>', 'Love the backlighting and the white background.', '2007-10-29 09:06:27.000000', NULL, 1),
