(4203189, 605549, 43774, '<td valign="top">Seems very blurry and pixelated. You need to save at a higher size, that would get rid of the compression artifacts.</td>', 'Seems very blurry and pixelated. You need to save at a higher size, that would get rid of the compression artifacts.', '2007-10-29 09:08:36.000000', NULL, 1),
