INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4204440, 605610, 5112, '<td valign="top">I think it''s just a tad of a stretch of the challenge, but it is a beautiful image, the best of the many fall images in the challenge (IMO).  ~9</td>', 'I think it''s just a tad of a stretch of the challenge, but it is a beautiful image, the best of the many fall images in the challenge (IMO).  ~9', '2007-10-29 19:19:11.000000', NULL, 1),
