(4204726, 605476, 49954, '<td valign="top">I think the problem is the amount of blood for no apparent cut yet, plus the blade is at the wrong angle.  A cut across the vein is easy to stop bleeding, whereas a long cut along the vein will remain open in time to bleed out.  Nice bloodwork though!</td>', 'I think the problem is the amount of blood for no apparent cut yet, plus the blade is at the wrong angle.  A cut across the vein is easy to stop bleeding, whereas a long cut along the vein will remain open in time to bleed out.  Nice bloodwork though!', '2007-10-29 22:23:52.000000', NULL, 1),
(4204853, 605727, 47205, '<td valign="top">This is an awesome shot. The lighting, the contrast, and I love the rays. Reflection with me is always a plus as well. Well done and I will be suprised if this isn''t top ten or ribbon.</td>', 'This is an awesome shot. The lighting, the contrast, and I love the rays. Reflection with me is always a plus as well. Well done and I will be suprised if this isn''t top ten or ribbon.', '2007-10-29 23:16:39.000000', NULL, 1),
