(4211294, 605911, 75034, '<td valign="top">This reminds me of eyewaves'' shot tension <a href="//www.dpchallenge.com/image.php?IMAGE_ID=383189" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/542/120/383189.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/542/120/383189.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/542/120/383189.jpg"/></a> wich won blue in another challenge. I think a little more focus would help this a lot and provide the detail that most everyone is looking for. It is a good attempt at something different for this kind of challenge.</td>', 'This reminds me of eyewaves'' shot tension  wich won blue in another challenge. I think a little more focus would help this a lot and provide the detail that most everyone is looking for. It is a good attempt at something different for this kind of challenge.', '2007-11-01 07:26:41.000000', NULL, 1),
(4211306, 605549, 75034, '<td valign="top">Good deep tones on the red and the reflection in the water works well in this shot. If I could offer one thing IMHO I would have waited a little longer to get a little more detail in the forground, but other than that it works fine.</td>', 'Good deep tones on the red and the reflection in the water works well in this shot. If I could offer one thing IMHO I would have waited a little longer to get a little more detail in the forground, but other than that it works fine.', '2007-11-01 07:30:26.000000', NULL, 1),
