(4223931, 605727, 42567, '<td valign="top">Best picture ever!  I think its the tones is what I like best.  Well, the whole picture actually!   Many congratulations on your ribbon</td>', 'Best picture ever!  I think its the tones is what I like best.  Well, the whole picture actually!   Many congratulations on your ribbon', '2007-11-05 20:24:59.000000', NULL, 0),
(4224003, 605727, 20168, '<td valign="top">Sweet image for "the beginning of the end", with a powerful title to capture the escatalogical imagination. Congrats on your beautiful blue. I''ve you''ve got to know, I would have quickly switched places with you in this challenge finish! Teehee:) I appreciate your helpful insights in the PP details.</td>', 'Sweet image for "the beginning of the end", with a powerful title to capture the escatalogical imagination. Congrats on your beautiful blue. I''ve you''ve got to know, I would have quickly switched places with you in this challenge finish! Teehee:) I appreciate your helpful insights in the PP details.', '2007-11-05 20:56:55.000000', NULL, 0),
(4224031, 605824, 49804, '<td valign="top">Very incredible shot, love the feel to it, congrats on the first ribbon and the upgrade to the 5d, lookin forward to what you got next</td>', 'Very incredible shot, love the feel to it, congrats on the first ribbon and the upgrade to the 5d, lookin forward to what you got next', '2007-11-05 21:17:39.000000', NULL, 0),
