(4224072, 604196, 32108, '<td valign="top">Well done, congratulations. Long overdue!</td>', 'Well done, congratulations. Long overdue!', '2007-11-05 21:37:29.000000', NULL, 0),
(4224138, 605824, 6519, '<td valign="top">WTG, my new friend! Congratulations!<br/> <br/>What a shame we didn''t know about that ribbon during our outing - that would certainly have been worth a beer or two, huh?<br/> <br/>Enjoy your glory and make sure to get a screen shot of it.</td>', 'WTG, my new friend! Congratulations! What a shame we didn''t know about that ribbon during our outing - that would certainly have been worth a beer or two, huh? Enjoy your glory and make sure to get a screen shot of it.', '2007-11-05 22:28:30.000000', NULL, 0),
(4224247, 604196, 86293, '<td valign="top">Awesome picture, so good; love the message that you try to tell people good, you have a good heart :)</td>', 'Awesome picture, so good; love the message that you try to tell people good, you have a good heart :)', '2007-11-05 23:32:38.000000', NULL, 0),
(4224405, 605727, 86026, '<td valign="top">It''s a cool location. and could be a great image, but your post-processing is sloppy. I would re-do it with a little more precision. I can see your "brush" strokes all along the mountains. Soory, it''s a nice photo, but your post-processing, while being on the right track color and idea-wise, is just done very haphazardly.</td>', 'It''s a cool location. and could be a great image, but your post-processing is sloppy. I would re-do it with a little more precision. I can see your "brush" strokes all along the mountains. Soory, it''s a nice photo, but your post-processing, while being on the right track color and idea-wise, is just done very haphazardly.', '2007-11-06 01:13:21.000000', NULL, 0),
(4224410, 605727, 30495, '<td valign="top">ummmmmm.....this is absolutely gorgeous!!!!!!!!!!<br/>everything is perfect.</td>', 'ummmmmm.....this is absolutely gorgeous!!!!!!!!!!everything is perfect.', '2007-11-06 01:17:05.000000', NULL, 0),
(4224411, 605824, 30495, '<td valign="top">nothing to say but ''WOW!!!!!!''</td>', 'nothing to say but ''WOW!!!!!!''', '2007-11-06 01:17:39.000000', NULL, 0),
