(4224414, 604196, 34462, '<td valign="top">Roz, what an outstanding photo and an outstanding message. Congrats on your first ribbon. It is well deserved!</td>', 'Roz, what an outstanding photo and an outstanding message. Congrats on your first ribbon. It is well deserved!', '2007-11-06 01:23:14.000000', NULL, 0),
(4224426, 605645, 34462, '<td valign="top">I think this is an excellent shot. the DOF, the sharpness, the subject. It''s one of those quandaries as to why this didn''t score better.</td>', 'I think this is an excellent shot. the DOF, the sharpness, the subject. It''s one of those quandaries as to why this didn''t score better.', '2007-11-06 01:56:42.000000', NULL, 0),
